    >>> is_diagonal_interaction((2, 0))
    True
    >>> is_diagonal_interaction((1, 1, 2))
    False
    """
def is_diagonal_interaction(int_tuple: Any) -> object {
    nonzero_indices = [
        idx
        for idx in int_tuple
        if (idx != 0)
    ];
    return (len(`set(nonzero_indices)) == 1);
